476:     /// Internal handler for OSD record to produce a synchronized `TelemetryPoint`.
477:     fn handle_osd(&mut self, osd: OsdRecord) -> TelemetryPoint {
478:         // --- 1. Dual-Phase Monotonic Timestamp Reconstruction ---
479:         let (raw_ts, raw_elapsed) = if osd.fly_time_s > 0.0 {
480:             // Airborne Phase: Synchronize to official motor timer fly_time_s
481:             let elapsed = if let Some(t_takeoff) = self.takeoff_elapsed_s {
482:                 t_takeoff + osd.fly_time_s
483:             } else {
484:                 let t_ground = self.pre_takeoff_count as f64 * 0.1;
485:                 self.takeoff_elapsed_s = Some(t_ground);
486:                 t_ground + osd.fly_time_s
487:             };
488: 
489:             let ts = if self.details_log_start_ms > 0 {
490:                 self.details_log_start_ms + (elapsed * 1000.0).round() as i64
491:             } else {
492:                 (elapsed * 1000.0).round() as i64
493:             };
494:             (ts, elapsed)
495:         } else {
496:             // Pre-Takeoff Ground Phase: Advance in strict 100 ms increments (10 Hz cadence)
497:             let elapsed = self.pre_takeoff_count as f64 * 0.1;
498:             self.pre_takeoff_count += 1;
499: 
500:             let ts = if self.details_log_start_ms > 0 {
501:                 self.details_log_start_ms + (elapsed * 1000.0).round() as i64
502:             } else {
503:                 (elapsed * 1000.0).round() as i64
