### 5.4 Flight Log Ingestion: `POST /api/v1/upload`
Accepts raw `.txt` or `.DAT` binary logs via:
1. `multipart/form-data` (browser file picker or drag-and-drop).
2. Raw octet stream `application/octet-stream` (direct curl, script, or mobile LAN sync).

```rust
// src/routes/upload.rs
use axum::{
    body::Bytes,
    extract::{Multipart, State},
    http::{header::CONTENT_TYPE, HeaderMap},
    Json,
};
use serde::Serialize;
use flightreader_export::model::FlightMetadata;
use crate::error::ServerError;
use crate::state::AppState;

#[derive(Debug, Serialize)]
pub struct UploadResponse {
    pub status: &'static str,
    pub message: String,
    pub log_type: String,
    pub records_count: usize,
    pub duration_seconds: f64,
    pub metadata: FlightMetadata,
}

pub async fn upload_flight_log(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Bytes,
) -> Result<Json<UploadResponse>, ServerError> {
    let content_type = headers
        .get(CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");

    let raw_bytes: Vec<u8> = if content_type.starts_with("multipart/form-data") {
        // If multipart, extract file field using axum multipart helper
        // or extract from body stream
        extract_multipart_bytes(content_type, body).await?
    } else {
        // Raw binary direct payload
        body.to_vec()
    };

    if raw_bytes.is_empty() {
        return Err(ServerError::BadRequest("Uploaded flight log payload is empty".to_string()));
    }

    // Ingest and aggregate via flightreader-export engine
    let dataset = flightreader_export::aggregate_buffer(&raw_bytes, None)
        .map_err(ServerError::Export)?;

    let records_count = dataset.points.len();
    let duration_seconds = dataset.metadata.duration_seconds;
    let log_type = dataset.metadata.log_type.clone();
    let metadata = dataset.metadata.clone();

    // Atomically swap dataset in AppState and notify WebSocket subscribers
    state.set_dataset(dataset).await;

    Ok(Json(UploadResponse {
        status: "success",
        message: format!("Successfully parsed and loaded {} ({} telemetry points)", log_type, records_count),
        log_type,
        records_count,
        duration_seconds,
        metadata,
    }))
}

async fn extract_multipart_bytes(content_type: &str, body: Bytes) -> Result<Vec<u8>, ServerError> {
    // Parse multipart boundary and extract first file entry
    // Implemented via multer or axum::extract::Multipart
    let boundary = multer::parse_boundary(content_type)
        .map_err(|e| ServerError::Multipart(e.to_string()))?;

    let mut multipart = multer::Multipart::new(futures_util::stream::once(async move { Ok::<_, std::io::Error>(body) }), boundary);

    while let Some(mut field) = multipart.next_field().await.map_err(|e| ServerError::Multipart(e.to_string()))? {
        let mut bytes = Vec::new();
        while let Some(chunk) = field.chunk().await.map_err(|e| ServerError::Multipart(e.to_string()))? {
            bytes.extend_from_slice(&chunk);
        }
        if !bytes.is_empty() {
            return Ok(bytes);
        }
    }

    Err(ServerError::BadRequest("No file found in multipart upload".to_string()))
}
```

