## 6. Real-Time Scrubber WebSocket Synchronization (`src/routes/ws.rs`)

### 6.1 Scrubber Message Protocol
Timeline scrubbing runs at 60 FPS. When the user interacts with the timeline slider on any client, all connected clients, maps, charts, and virtual instruments update instantaneously without latency.

```rust
// src/routes/ws.rs
use axum::{
    extract::{
        ws::{Message, WebSocket, WebSocketUpgrade},
        State,
    },
    response::Response,
};
use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use tokio::sync::broadcast;
use crate::state::AppState;

/// Bidirectional message protocol for 60 FPS timeline scrubber synchronization.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", content = "payload")]
pub enum WsScrubMessage {
    /// Dispatched when the user scrubs to a point index or during playback tick.
    Scrub {
        index: usize,
        timestamp_ms: i64,
    },
    /// Playback state changes (Play, Pause, Speed).
    Playback {
        playing: bool,
        speed: f64,
        current_index: usize,
    },
    /// Notification that a new flight dataset was ingested.
    DatasetLoaded {
        total_points: usize,
        duration_seconds: f64,
        log_type: String,
    },
    /// Heartbeat ping.
    Ping,
    /// Heartbeat pong.
    Pong,
    /// Error notification.
    Error {
        message: String,
    },
}

pub async fn ws_handler(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
) -> Response {
    ws.on_upgrade(move |socket| handle_ws_socket(socket, state))
}

async fn handle_ws_socket(socket: WebSocket, state: AppState) {
    let (mut ws_sender, mut ws_receiver) = socket.split();
    let mut broadcast_rx = state.ws_broadcaster.subscribe();

    // Spawn bidirectional relay task
    let mut send_task = tokio::spawn(async move {
        while let Ok(msg) = broadcast_rx.recv().await {
            if let Ok(json_str) = serde_json::to_string(&msg) {
                if ws_sender.send(Message::Text(json_str)).await.is_err() {
                    break;
                }
            }
        }
    });

    let broadcaster = state.ws_broadcaster.clone();
    let mut recv_task = tokio::spawn(async move {
        while let Some(Ok(message)) = ws_receiver.next().await {
            match message {
                Message::Text(text) => {
                    if let Ok(cmd) = serde_json::from_str::<WsScrubMessage>(&text) {
                        match cmd {
                            WsScrubMessage::Scrub { .. } | WsScrubMessage::Playback { .. } => {
                                let _ = broadcaster.send(cmd);
                            }
                            WsScrubMessage::Ping => {
                                let _ = broadcaster.send(WsScrubMessage::Pong);
                            }
                            _ => {}
                        }
                    }
                }
                Message::Close(_) => break,
                _ => {}
            }
        }
    });

    // Terminate cleanly when either side disconnects
    tokio::select! {
        _ = (&mut send_task) => recv_task.abort(),
        _ = (&mut recv_task) => send_task.abort(),
    };
}
```

